  it.todo("ratint_logpart(Poly(12, x, domain='ZZ'),");
  it("ratint_ratpart(Poly(1, x, domain='ZZ'),", () => {
    const x = new Sym('x');
    const v1 = ratintRatpart(Poly.from(Rational.of(1n, 1n, { gcd: 1n }), [x], { domain: 'ZZ', pure: false }), Poly.from(add(Rational.of(1n, 1n, { gcd: 1n }), x), [x], { domain: 'ZZ', pure: false }), x);
    expect(sympyMatches([at(v1, 0), at(v1, 1)], '(0, 1/(x + 1))')).toBe(true);
  });
